"""Word-level unified diff of two text files (stdlib only).

Usage:
    python3 minidiff.py FILE_A FILE_B

Prints only the changed hunks in unified style with one line of
context. Exits 1 when the files differ, 0 when identical, 2 on
usage or I/O errors.
"""

import difflib
import sys

CONTEXT = 1
# Sentinel standing in for each line's terminator; an object so it can
# never collide with a word from the input.
NL = object()


def read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def tokenize(lines):
    """Words per line, each followed by the NL sentinel."""
    toks = []
    for line in lines:
        toks.extend(line.split())
        toks.append(NL)
    return toks


def line_bounds(toks, nlines):
    """Per-line token spans (start, end), each including the line's sentinel."""
    bounds = []
    pos = 0
    for _ in range(nlines):
        end = toks.index(NL, pos)
        bounds.append((pos, end + 1))
        pos = end + 1
    return bounds


def line_of(bounds, pos, toks_len):
    """Line index containing token pos, or len(bounds) if pos is past the end."""
    if pos >= toks_len:
        return len(bounds)
    for k, (s, e) in enumerate(bounds):
        if s <= pos < e:
            return k
    return len(bounds)


def changed_lines(bounds, start, end):
    return [k for k, (s, e) in enumerate(bounds) if s < end and e > start]


def word_events(lines_a, lines_b):
    """Yield (old_lines, new_lines, anchor, shift) per non-equal diff span.

    old_lines/new_lines are the contiguous line ranges touched by the span.
    anchor is the old line index at the span's start (the insertion point
    for pure insertions). shift is (new lines inserted so far) minus
    (old lines deleted so far) before the span, used to number lines on
    the new side when the files differ in line count.
    """
    toks_a, toks_b = tokenize(lines_a), tokenize(lines_b)
    bounds_a = line_bounds(toks_a, len(lines_a))
    bounds_b = line_bounds(toks_b, len(lines_b))
    matcher = difflib.SequenceMatcher(None, toks_a, toks_b, autojunk=False)
    shift = 0
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            continue
        oa = changed_lines(bounds_a, i1, i2)
        ob = changed_lines(bounds_b, j1, j2)
        if not oa and not ob:
            continue
        yield oa, ob, line_of(bounds_a, i1, len(toks_a)), shift
        shift += len(ob) - len(oa)


def render_hunks(lines_a, lines_b, events):
    """Group events <= CONTEXT clean lines apart and format them as hunks."""
    groups = []
    for ev in events:
        oa, ob = ev[0], ev[1]
        if groups:
            poa, pob = groups[-1][-1][0], groups[-1][-1][1]
            gap_a = oa[0] - poa[-1] - 1 if oa and poa else 0
            gap_b = ob[0] - pob[-1] - 1 if ob and pob else 0
            if gap_a <= CONTEXT and gap_b <= CONTEXT:
                groups[-1].append(ev)
                continue
        groups.append([ev])

    hunks = []
    for group in groups:
        rows = []  # (prefix, text, old_no, new_no)

        def ctx(k, shift):
            rows.append((" ", " ".join(lines_a[k].split()), k + 1, k + shift + 1))

        first = group[0]
        start = first[0][0] if first[0] else first[2]
        for k in range(max(0, start - CONTEXT), start):
            ctx(k, first[3])
        prev_old = start - 1

        for oa, ob, anchor, shift in group:
            if oa:
                for k in range(prev_old + 1, oa[0]):
                    ctx(k, shift)
                for k in oa:
                    rows.append(("-", " ".join(lines_a[k].split()), k + 1, None))
                for k in ob:
                    rows.append(("+", " ".join(lines_b[k].split()), None, k + shift + 1))
                prev_old = oa[-1]
            else:
                for k in range(prev_old + 1, anchor):
                    ctx(k, shift)
                for k in ob:
                    rows.append(("+", " ".join(lines_b[k].split()), None, k + shift + 1))
                prev_old = anchor - 1

        last = group[-1]
        last_shift = last[3] + len(last[1]) - len(last[0])
        for k in range(prev_old + 1, min(len(lines_a), prev_old + 1 + CONTEXT)):
            ctx(k, last_shift)

        old_rows = [r for r in rows if r[0] in (" ", "-")]
        new_rows = [r for r in rows if r[0] in (" ", "+")]
        old_start = old_rows[0][2] if old_rows else start
        new_start = new_rows[0][3] if new_rows else start + first[3]
        out = ["@@ -%d,%d +%d,%d @@" % (old_start, len(old_rows), new_start, len(new_rows))]
        out += ["%s%s" % (prefix, text) for prefix, text, _, _ in rows]
        hunks.append("\n".join(out))
    return hunks


def main(argv):
    if len(argv) != 3:
        print("usage: minidiff.py FILE_A FILE_B", file=sys.stderr)
        return 2
    try:
        lines_a = read_lines(argv[1])
        lines_b = read_lines(argv[2])
    except OSError as exc:
        print("minidiff: %s" % exc, file=sys.stderr)
        return 2
    events = list(word_events(lines_a, lines_b))
    for hunk in render_hunks(lines_a, lines_b, events):
        print(hunk)
    return 1 if events else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
