"""Word-level unified diff of two text files (stdlib only).

Usage:
    python3 minidiff.py FILE_A FILE_B

Prints only the changed hunks in unified style with one line of
context. Exits 1 when the files differ, 0 when identical, 2 on
usage or I/O errors.
"""

import difflib
import sys

CONTEXT = 1
# Sentinel standing in for each line's terminator; an object so it can
# never collide with a word from the input.
NL = object()


def read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def tokenize(lines):
    """Words per line, each followed by the NL sentinel."""
    toks = []
    for line in lines:
        toks.extend(line.split())
        toks.append(NL)
    return toks


def line_bounds(toks, nlines):
    """Per-line token spans (start, end), each including the line's sentinel."""
    bounds = []
    pos = 0
    for _ in range(nlines):
        end = toks.index(NL, pos)
        bounds.append((pos, end + 1))
        pos = end + 1
    return bounds


def line_of(bounds, pos, toks_len):
    """Line index containing token pos, or len(bounds) if pos is past the end."""
    if pos >= toks_len:
        return len(bounds)
    for k, (s, e) in enumerate(bounds):
        if s <= pos < e:
            return k
    return len(bounds)


def lines_in(bounds, start, end):
    return [k for k, (s, e) in enumerate(bounds) if s < end and e > start]


def any_overlap(spans, lo, hi):
    return any(s < hi and e > lo for s, e in spans)


def partner_line(k, bounds_src, bounds_dst, pos_map, dst_len):
    """Line in the other file holding the mapped tokens of line k, if any."""
    s, e = bounds_src[k]
    for p in range(s, e):
        if p in pos_map:
            return line_of(bounds_dst, pos_map[p], dst_len)
    return None


def analyze(lines_a, lines_b):
    """Word-level diff of two line lists.

    Returns (has_diff, events). Each event is (old_lines, new_lines,
    anchor, shift): the contiguous line ranges touched by one non-equal
    span, the old line index at the span's start (insertion point for
    pure insertions), and (new lines inserted so far) minus (old lines
    deleted so far) before the span, used to number the new side when
    the line counts differ.

    A line whose only changed token is its terminator and whose mapped
    partner line is word-identical is demoted to context: LCS can match
    terminators across a gap when lines are inserted or deleted, which
    would otherwise flag a textually unchanged line as changed.
    """
    toks_a, toks_b = tokenize(lines_a), tokenize(lines_b)
    bounds_a = line_bounds(toks_a, len(lines_a))
    bounds_b = line_bounds(toks_b, len(lines_b))
    matcher = difflib.SequenceMatcher(None, toks_a, toks_b, autojunk=False)
    opcodes = matcher.get_opcodes()
    has_diff = any(tag != "equal" for tag, *rest in opcodes)
    spans = [(i1, i2, j1, j2) for tag, i1, i2, j1, j2 in opcodes if tag != "equal"]

    a2b, b2a = {}, {}
    for tag, i1, i2, j1, j2 in opcodes:
        if tag == "equal":
            for k in range(i2 - i1):
                a2b[i1 + k] = j1 + k
                b2a[j1 + k] = i1 + k

    dirty_a = [(i1, i2) for i1, i2, j1, j2 in spans]
    dirty_b = [(j1, j2) for i1, i2, j1, j2 in spans]

    def line_status(bounds, dirty):
        word_dirty, nl_dirty = [], []
        for s, e in bounds:
            word_dirty.append(any_overlap(dirty, s, e - 1))
            nl_dirty.append(any_overlap(dirty, e - 1, e))
        return word_dirty, nl_dirty

    word_dirty_a, nl_dirty_a = line_status(bounds_a, dirty_a)
    word_dirty_b, nl_dirty_b = line_status(bounds_b, dirty_b)

    demoted_a = [False] * len(lines_a)
    for k, (s, e) in enumerate(bounds_a):
        if nl_dirty_a[k] and not word_dirty_a[k]:
            m = partner_line(k, bounds_a, bounds_b, a2b, len(toks_b))
            if m is not None and lines_a[k].split() == lines_b[m].split():
                demoted_a[k] = True

    demoted_b = [False] * len(lines_b)
    for k, (s, e) in enumerate(bounds_b):
        if nl_dirty_b[k] and not word_dirty_b[k]:
            m = partner_line(k, bounds_b, bounds_a, b2a, len(toks_a))
            if m is not None and lines_b[k].split() == lines_a[m].split():
                demoted_b[k] = True

    events = []
    shift = 0
    for i1, i2, j1, j2 in spans:
        raw_oa = lines_in(bounds_a, i1, i2)
        raw_ob = lines_in(bounds_b, j1, j2)
        oa = [k for k in raw_oa if not demoted_a[k]]
        ob = [k for k in raw_ob if not demoted_b[k]]
        if not oa and not ob:
            continue
        events.append((oa, ob, line_of(bounds_a, i1, len(toks_a)), shift))
        shift += len(raw_oa) - len(raw_ob)
    return has_diff, events


def render_hunks(lines_a, lines_b, events):
    """Group events <= CONTEXT clean lines apart and format them as hunks."""
    groups = []
    for ev in events:
        oa, ob = ev[0], ev[1]
        if groups:
            poa, pob = groups[-1][-1][0], groups[-1][-1][1]
            gap_a = oa[0] - poa[-1] - 1 if oa and poa else 0
            gap_b = ob[0] - pob[-1] - 1 if ob and pob else 0
            if gap_a <= CONTEXT and gap_b <= CONTEXT:
                groups[-1].append(ev)
                continue
        groups.append([ev])

    hunks = []
    for group in groups:
        rows = []  # (prefix, text, old_no, new_no)

        def ctx(k, shift):
            rows.append((" ", " ".join(lines_a[k].split()), k + 1, k + shift + 1))

        first = group[0]
        start = first[0][0] if first[0] else first[2]
        for k in range(max(0, start - CONTEXT), start):
            ctx(k, first[3])
        prev_old = start - 1

        for oa, ob, anchor, shift in group:
            if oa:
                for k in range(prev_old + 1, oa[0]):
                    ctx(k, shift)
                for k in oa:
                    rows.append(("-", " ".join(lines_a[k].split()), k + 1, None))
                for k in ob:
                    rows.append(("+", " ".join(lines_b[k].split()), None, k + shift + 1))
                prev_old = oa[-1]
            else:
                for k in range(prev_old + 1, anchor):
                    ctx(k, shift)
                for k in ob:
                    rows.append(("+", " ".join(lines_b[k].split()), None, k + shift + 1))
                prev_old = anchor - 1

        last = group[-1]
        last_shift = last[3] + len(last[1]) - len(last[0])
        for k in range(prev_old + 1, min(len(len(lines_a) and lines_a), prev_old + 1 + CONTEXT)):
            ctx(k, last_shift)

        old_rows = [r for r in rows if r[0] in (" ", "-")]
        new_rows = [r for r in rows if r[0] in (" ", "+")]
        old_start = old_rows[0][2] if old_rows else start
        new_start = new_rows[0][3] if new_rows else start + first[3]
        out = ["@@ -%d,%d +%d,%d @@" % (old_start, len(old_rows), new_start, len(new_rows))]
        out += ["%s%s" % (prefix, text) for prefix, text, _, _ in rows]
        hunks.append("\n".join(out))
    return hunks


def main(argv):
    if len(argv) != 3:
        print("usage: minidiff.py FILE_A FILE_B", file=sys.stderr)
        return 2
    try:
        lines_a = read_lines(argv[1])
        lines_b = read_lines(argv[2])
    except OSError as exc:
        print("minidiff: %s" % exc, file=sys.stderr)
        return 2
    has_diff, events = analyze(lines_a, lines_b)
    for hunk in render_hunks(lines_a, lines_b, events):
        print(hunk)
    return 1 if has_diff else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
